import java.util.Scanner;

public class Main {
    static int m, n, p;
    static long[] dp = new long[505];
    static long[] cnt = new long[505];
    static long[][] dp2 = new long[505][505];
    static long[][] tot = new long[505][505];
    static long[] fac = new long[505];
    static long[] invfac = new long[505];
    static int tmp, zh;

    static long bin_pow(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % p;
            base = base * base % p;
            exp >>= 1;
        }
        return res;
    }

    static long nCr(int a, int b) {
        return fac[a] * invfac[b] % p * invfac[a - b] % p;
    }

    static long triangle_sum(int x) {
        return (long) x * (x + 1) / 2 % p;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        p = sc.nextInt();

        fac[0] = 1;
        for (int i = 1; i <= 500; i++) {
            fac[i] = fac[i - 1] * i % p;
        }
        invfac[500] = bin_pow(fac[500], p - 2);
        for (int i = 499; i >= 0; i--) {
            invfac[i] = invfac[i + 1] * (i + 1) % p;
        }

        cnt[0] = 1;
        dp[0] = 0;
        cnt[1] = 2;
        dp[1] = 0;

        for (int i = 2; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                zh = (int) nCr(i - 1, j - 1);
                long tmpVal = cnt[j - 1] * cnt[i - j] % p * zh % p;

                long part1 = tmpVal * triangle_sum(j - 1) % p;
                long part2 = zh * j % p * ((dp[j - 1] * cnt[i - j] % p + dp[i - j] * cnt[j - 1] % p) % p) % p;
                dp[i] = (dp[i] + part1 + part2) % p;

                cnt[i] = (cnt[i] + tmpVal * j) % p;

                long part3 = tmpVal * triangle_sum(i - j) % p;
                long part4 = zh * (i - j + 1) % p * ((dp[j - 1] * cnt[i - j] % p + dp[i - j] * cnt[j - 1] % p) % p) % p;
                dp[i] = (dp[i] + part3 + part4) % p;

                cnt[i] = (cnt[i] + tmpVal * (i - j + 1)) % p;
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp2[i][j] = 0;
                tot[i][j] = 0;
            }
        }
        dp2[0][0] = 0;
        tot[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(m, i); j++) {
                dp2[i][j] = dp2[i - 1][j];
                tot[i][j] = tot[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    if (k < i) {
                        zh = (int) nCr(j, k);
                        long val1 = dp[k] * zh % p * tot[i - k - 1][j - k] % p;
                        long val2 = dp2[i - k - 1][j - k] * zh % p * cnt[k] % p;
                        dp2[i][j] = (dp2[i][j] + val1 + val2) % p;

                        long totVal = cnt[k] * tot[i - k - 1][j - k] % p * zh % p;
                        tot[i][j] = (tot[i][j] + totVal) % p;
                    } else {
                        dp2[i][j] = (dp2[i][j] + dp[i]) % p;
                        tot[i][j] = (tot[i][j] + cnt[i]) % p;
                    }
                }
            }
        }

        System.out.println(dp2[n][m]);
        sc.close();
    }
}
